/* Study 31: local article/history and route previews only. No browser, clipboard or share APIs. */
(function(){
'use strict';
const E=id=>document.getElementById(id),T=window.RelaxeStudyTheme,config={appearance:'light',palette:'blue',text:'1',width:'390'},pages=[{title:'Trail notes',path:'trail-notes',article:'A slower way through the forest'},{title:'Choosing a route',path:'route-planning',article:'Choose a route for the day you have'}];
let page=0,open=false,stage='actions',origin=null,holdTimer=null,holdPoint=null,ignoreContextUntil=0;
const copyByAccount=new Map();
function copySettings(){const account=E('browser-account').value;if(!copyByAccount.has(account))copyByAccount.set(account,{showCopy:true,longPressCopy:true});return copyByAccount.get(account)}
function cancelHold(){clearTimeout(holdTimer);holdTimer=null;holdPoint=null}
function url(){return 'https://example.com/'+pages[page].path}
function theme(){const settings={foundation:'selected',...config},direction=T.directions[0],phone=E('browser-phone');for(const [key,value]of Object.entries(T.tokens(direction,settings)))phone.style.setProperty(key,value);T.setStyleAttributes(phone,direction,settings);phone.style.setProperty('--w',config.width+'px');phone.style.setProperty('--h',({360:800,390:844,600:960,720:480}[config.width])+'px');phone.dataset.largeText=String(+config.text>=2);window.RelaxeShell?.setContext({account:E('browser-account').value,...config})}
function setOpen(value,nextStage='actions',trigger){cancelHold();if(value&&!open)origin=trigger||E('browser-more');stage=nextStage;open=value;render();E('browser-overlay').hidden=!open;E('browser-more').setAttribute('aria-expanded',String(open));for(const child of E('browser-phone').children)if(child!==E('browser-overlay'))child.inert=open;(open?E('browser-menu-close'):(origin||E('browser-more'))).focus({preventScroll:true})}
function backToActions(){stage='actions';render();E('browser-menu-actions').querySelector('[data-browser-action="settings"]').focus({preventScroll:true})}
function route(label){const message='Route preview: '+label+' — '+url()+'. No external action was performed.';if(open)setOpen(false);E('browser-result').hidden=false;E('browser-result').textContent=message;E('browser-feedback').textContent=message}
function render(){cancelHold();E('browser-title').textContent=pages[page].title;E('browser-url').textContent='example.com/'+pages[page].path;E('browser-menu-url').textContent=url();E('browser-article-title').textContent=pages[page].article;E('browser-next').hidden=page===1;const settings=copySettings();E('browser-copy').hidden=!settings.showCopy;E('browser-hold-fixture').disabled=!settings.longPressCopy;E('browser-setting-copy').checked=settings.showCopy;E('browser-setting-hold').checked=settings.longPressCopy;E('browser-menu-title').textContent=stage==='settings'?'Browser settings':'Browser actions';E('browser-menu-close').setAttribute('aria-label',stage==='settings'?'Close browser settings':'Close browser actions');E('browser-menu-back').hidden=stage!=='settings';E('browser-settings').hidden=stage!=='settings';E('browser-menu-actions').hidden=stage==='settings';E('browser-settings-scope').textContent='Applies to '+(E('browser-account').value==='guest'?'Guest':'u/weekendreader');E('browser-menu-actions').replaceChildren();const actions=[['refresh','Refresh'],['share','Share link'],['copy','Copy link'],['settings','Browser settings']];for(const [id,label]of actions){const button=document.createElement('button');button.type='button';button.dataset.browserAction=id;button.textContent=label;button.addEventListener('click',()=>{if(id==='settings'){stage='settings';render();E('browser-menu-scroll').scrollTop=0;E('browser-menu-close').focus({preventScroll:true})}else route(label)});E('browser-menu-actions').append(button)}}
for(const [id,key]of [['browser-appearance','appearance'],['browser-palette','palette'],['browser-scale','text'],['browser-width','width']])E(id).addEventListener('change',event=>{config[key]=event.target.value;theme()});
E('browser-settings-preview').addEventListener('click',()=>setOpen(true,'settings',E('browser-settings-preview')));
E('browser-menu-back').innerHTML=T.icon('back');E('browser-menu-back').addEventListener('click',backToActions);
E('browser-settings-done').addEventListener('click',()=>setOpen(false));
for(const [id,key]of [['browser-setting-copy','showCopy'],['browser-setting-hold','longPressCopy']])E(id).addEventListener('change',event=>{cancelHold();copySettings()[key]=event.target.checked;render();E('browser-feedback').textContent='Browser Copy settings updated in this account fixture only. Both settings default to enabled; changes remain page-memory only.'});
E('browser-account').addEventListener('change',()=>{if(open)setOpen(false);page=0;render();theme();E('browser-feed').scrollTop=0;E('browser-result').hidden=true;E('browser-feedback').textContent='Account fixture reset; real account/privacy behavior is not tested.'});
E('browser-next').addEventListener('click',()=>{page=1;render();E('browser-result').hidden=true;E('browser-feed').scrollTop=0;E('browser-article-title').focus({preventScroll:true});E('browser-feedback').textContent='Second local page fixture. All actions now target its URL.'});
E('browser-back-fixture').addEventListener('click',()=>{if(open){if(stage==='settings')backToActions();else setOpen(false);return}if(page>0){page--;render();E('browser-result').hidden=true;E('browser-feed').scrollTop=0;E('browser-feedback').textContent='Back returned to the first local page.'}else route('Close in-app browser')});
E('browser-reset').addEventListener('click',()=>{if(open)setOpen(false);page=0;render();E('browser-result').hidden=true;E('browser-feed').scrollTop=0;E('browser-feedback').textContent='First local page restored; no WebView restoration was performed.'});
// The copy glyph follows the existing upstream drawable; the native helper remains unchanged.
E('browser-copy').innerHTML='<svg class="foundation-icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" stroke="none" d="M16 1H4C2.9 1 2 1.9 2 3v14h2V3h12V1ZM19 5H8C6.9 5 6 5.9 6 7v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2ZM19 21H8V7h11v14Z"/></svg>';
E('browser-copy').addEventListener('click',()=>route('Copy link'));
E('browser-hold-fixture').addEventListener('click',()=>{cancelHold();if(copySettings().longPressCopy)route('Copy link')});
const bar=document.querySelector('.browser-bar');
bar.addEventListener('pointerdown',event=>{cancelHold();if(!copySettings().longPressCopy||event.pointerType==='mouse'||!event.isPrimary||event.button!==0||event.target.closest('button'))return;holdPoint={x:event.clientX,y:event.clientY};holdTimer=setTimeout(()=>{holdTimer=null;holdPoint=null;ignoreContextUntil=Date.now()+1200;route('Copy link')},600)});
bar.addEventListener('pointermove',event=>{if(holdPoint&&Math.hypot(event.clientX-holdPoint.x,event.clientY-holdPoint.y)>10)cancelHold()});
for(const name of ['pointerup','pointercancel','pointerleave'])bar.addEventListener(name,cancelHold);
bar.addEventListener('contextmenu',event=>{if(event.target.closest('button'))return;event.preventDefault();cancelHold();if(!copySettings().longPressCopy||Date.now()<ignoreContextUntil)return;route('Copy link')});
window.addEventListener('blur',cancelHold);document.addEventListener('visibilitychange',cancelHold);
E('browser-close').innerHTML=T.icon('close');E('browser-external').innerHTML=T.icon('external');E('browser-more').innerHTML=T.icon('more');E('browser-menu-close').innerHTML=T.icon('close');E('browser-close').addEventListener('click',()=>route('Close in-app browser'));E('browser-external').addEventListener('click',()=>route('Open in browser'));E('browser-more').addEventListener('click',()=>setOpen(true));E('browser-menu-close').addEventListener('click',()=>setOpen(false));
E('browser-overlay').addEventListener('click',event=>{if(event.target===E('browser-overlay'))setOpen(false)});E('browser-overlay').addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();if(stage==='settings')backToActions();else setOpen(false)}if(event.key!=='Tab')return;const items=[...E('browser-panel').querySelectorAll('button,input,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
render();theme();document.addEventListener('relaxe-shell-ready',()=>{theme();for(const child of E('browser-phone').children)if(child!==E('browser-overlay'))child.inert=open},{once:true});
})();
